    static void draw(GuiGraphicsExtractor g, God god, int x, int y) {
        int[] px = god == God.RA ? SUN : THOR;
        for (int i = 0; i < 256; i++) {
            int c = px[i];
            if ((c >>> 24) == 0) continue;
            int xx = x + (i % 16), yy = y + (i / 16);
            g.fill(xx, yy, xx + 1, yy + 1, c);
        }
    }

